import { useInfiniteQuery, useSuspenseQuery } from "@tanstack/react-query"
import { createFileRoute } from "@tanstack/react-router"
import { Search } from "lucide-react"
import { Suspense } from "react"

import { ItemsService } from "@/client"
import { DataTable } from "@/components/Common/DataTable"
import AddItem from "@/components/Items/AddItem"
import { columns } from "@/components/Items/columns"
import PendingItems from "@/components/Pending/PendingItems"

const PAGE_SIZE = 20 // Define a page size

function getItemsQueryOptions() {
  return {
    // Use queryKey to uniquely identify this query with pagination state
    queryKey: ["items", "infinite"],
    // Initial page parameters
    initialPageParam: 0,
    // Function to fetch pages
    queryFn: ({ pageParam }) => {
      return ItemsService.readItems({ skip: pageParam, limit: PAGE_SIZE })
    },
    // Function to get the next page's parameter
    getNextPageParam: (lastPage, allPages) => {
      // lastPage.data is the array of items for the current page
      // lastPage.count is the total number of items
      const lastItemInPage = lastPage.data[lastPage.data.length - 1]
      if (!lastItemInPage) return undefined // No items in the last page

      const currentSkip = lastPage.data[0].__skip // Assuming __skip is available or derive from index
      const totalItems = lastPage.count

      // Calculate the next skip value
      const nextSkip = currentSkip + PAGE_SIZE
      if (nextSkip >= totalItems) {
        return undefined // No more pages
      }
      return nextSkip
    },
    // Keep previous data while fetching next page
    keepPreviousData: true,
  }
}

export const Route = createFileRoute("/_layout/items")({
  component: Items,
})

function ItemsTableContent() {
  const {
    data: pagesData,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    isLoading, // Added isLoading for initial loading state
  } = useInfiniteQuery(getItemsQueryOptions())

  // Flatten all items from all pages
  const allItems = pagesData?.pages.flatMap((page) => page.data) ?? []

  if (isLoading) {
    // Show a general loading state while the first page is being fetched
    return (
      <div className="flex flex-col items-center justify-center text-center py-12">
        <PendingItems />
      </div>
    )
  }

  if (allItems.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center text-center py-12">
        <Search className="h-8 w-8 text-muted-foreground" />
        <h3 className="text-lg font-semibold">You don't have any items yet</h3>
      </div>
    )
  }

  return (
    <div>
      <DataTable columns={columns} data={allItems} />
      {hasNextPage && (
        <div className="flex justify-center mt-4">
